<template><section class="card"><h1>회원가입</h1><form class="form" @submit.prevent="submit"><div class="field"><label>아이디</label><input v-model="form.username" required></div><div class="field"><label>이메일</label><input v-model="form.email" type="email"></div><div class="field"><label>비밀번호</label><input v-model="form.password" type="password" required></div><div class="field"><label>비밀번호 확인</label><input v-model="form.password_confirm" type="password" required></div><button>회원가입</button><p v-if="error" class="error">{{error}}</p></form></section></template>
<script setup>import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAccountStore } from '@/stores/account'; const router=useRouter(); const store=useAccountStore(); const form=reactive({username:'',email:'',password:'',password_confirm:''}); const error=ref(''); const submit=async()=>{try{await store.signUp(form); router.push({name:'HomeView'})}catch(e){error.value=JSON.stringify(e.response?.data||e.message,null,2)}}</script>
